import math

def _is_int(v): return isinstance(v, int) and not isinstance(v, bool)

def _number(v):
    if isinstance(v, bool): raise ValueError
    if isinstance(v, int): return v
    if isinstance(v, float):
        if math.isnan(v) or math.isinf(v): raise ValueError
        return v
    raise ValueError

def _require_int(v, name):
    if not _is_int(v): raise ValueError(f"{name} must be an integer")
    return v

def _wrapper_records(payload):
    if not isinstance(payload, dict) or set(payload) != {"name", "result"}:
        raise ValueError("input must be a component wrapper")
    result = payload["result"]
    if not isinstance(result, dict) or "records" not in result:
        raise ValueError("wrapper result must contain records")
    records = result["records"]
    if not isinstance(records, list):
        raise ValueError("records must be a list")
    return records

def _record(r):
    if not isinstance(r, dict): raise ValueError
    source = r.get("source"); ident = r.get("id")
    if not isinstance(source, str) or not source.strip(): raise ValueError
    if not isinstance(ident, str) or not ident.strip(): raise ValueError
    score = r.get("score")
    if score is None: raise ValueError
    _number(score)
    tags = r.get("tags")
    if not isinstance(tags, list): raise ValueError
    for t in tags:
        if not isinstance(t, str): raise ValueError
    category = r.get("category")
    if not isinstance(category, str) or category not in ("prepare","copy","verify"):
        raise ValueError
    return r

def transform(payloads, contract):
    if not isinstance(payloads, list) or not isinstance(contract, dict):
        raise ValueError
    inputs = contract.get("inputs")
    if not isinstance(inputs, list) or len(payloads) != len(inputs):
        raise ValueError
    threshold = _require_int(contract.get("threshold"), "threshold")
    only_if_blocking = contract.get("only_if_blocking", False)
    if not isinstance(only_if_blocking, bool):
        raise ValueError("only_if_blocking must be a boolean")
    merged = {}
    for p in payloads:
        for r in _wrapper_records(p):
            rec = _record(r)
            key = (rec["source"], rec["id"])
            if key in merged and merged[key] != rec:
                raise ValueError("source/id conflict")
            merged[key] = rec
    retained = list(merged.values())
    if only_if_blocking:
        blocking = any(("blocking" in r["tags"]) and r["score"] >= threshold for r in retained)
        if not blocking:
            retained = []
    records = sorted(retained, key=lambda r:(r["source"], r["id"]))
    if not retained:
        return {"name": contract["name"], "result": {"records": [], "blocked": False, "waves": [], "critical_path": [], "makespan": 0, "earliest_finish": {}}}
    order = {"prepare":0, "copy":1, "verify":2}
    nodes = []
    for r in retained:
        full = f"{r['source']}:{r['id']}"
        nodes.append({
            "full": full,
            "category": r["category"],
            "duration": 1 + (r["score"] // 5),
        })
    nodes.sort(key=lambda n:(order[n["category"]], n["full"]))
    by_cat = {}
    for n in nodes:
        by_cat.setdefault(n["category"], []).append(n)
    waves = []
    for cat in ("prepare","copy","verify"):
        if cat in by_cat:
            waves.append([n["full"] for n in sorted(by_cat[cat], key=lambda n:n["full"])])
    done = []
    for cat in ("prepare","copy","verify"):
        cat_nodes = sorted(by_cat.get(cat, []), key=lambda n:n["full"])
        for n in cat_nodes:
            if not done:
                n["finish"] = n["duration"]
                n["path"] = [n["full"]]
            else:
                maxf = max(p["finish"] for p in done)
                cands = [p for p in done if p["finish"] == maxf]
                cands.sort(key=lambda p: p["path"])
                chosen = cands[0]
                n["finish"] = n["duration"] + chosen["finish"]
                n["path"] = chosen["path"] + [n["full"]]
        done.extend(cat_nodes)
    # terminal nodes
    last_cat = None
    for cat in ("prepare","copy","verify"):
        if cat in by_cat:
            last_cat = cat
    terminals = by_cat[last_cat]
    terminals_sorted = sorted(terminals, key=lambda n: (-n["finish"], n["path"]))
    endpoint = terminals_sorted[0]
    critical_path = endpoint["path"]
    makespan = max(n["finish"] for n in nodes)
    earliest_finish = {n["full"]: n["finish"] for n in nodes}
    return {"name": contract["name"], "result": {
        "records": records,
        "blocked": False,
        "waves": waves,
        "critical_path": critical_path,
        "makespan": makespan,
        "earliest_finish": earliest_finish,
    }}
