    if not isinstance(contract.get("name"), str) or not contract["name"]:
        raise ValueError("contract name must be a non-empty string")

    inputs = contract.get("inputs")
    if not isinstance(inputs, list) or len(payloads) != len(inputs):
        raise ValueError("payloads must match contract inputs")

    threshold = _require_int(contract.get("threshold"), "threshold")
    only_if_blocking = contract.get("only_if_blocking", False)
    if not isinstance(only_if_blocking, bool):
        raise ValueError("only_if_blocking must be a boolean")

    merged = {}
    for payload in payloads:
        for record in _wrapper_records(payload):
            rec = _record(record)
            key = (rec["source"], rec["id"])
            if key in merged and merged[key] != rec:
                raise ValueError("conflicting records for the same source/id")
            merged[key] = rec

    retained = list(merged.values())
    if only_if_blocking:
        blocking = any("blocking" in r["tags"] and r["score"] >= threshold for r in retained)
        if not blocking:
            retained = []

    records = sorted(retained, key=lambda r: (r["source"], r["id"]))

    if not retained:
        return {
            "name": contract["name"],
            "result": {
                "records": [],
                "blocked": False,
                "waves": [],
                "critical_path": [],
                "makespan": 0,
                "earliest_finish": {},
            },
        }

    category_order = {"prepare": 0, "copy": 1, "verify": 2}

    nodes = []
    for record in retained:
        full_id = f"{record['source']}:{record['id']}"
        nodes.append({
            "full": full_id,
            "category": record["category"],
            "duration": 1 + (record["score"] // 5),
        })
    nodes.sort(key=lambda n: (category_order[n["category"]], n["full"]))

    by_category = {}
    for node in nodes:
        by_category.setdefault(node["category"], []).append(node)

    waves = []
    for category in ("prepare", "copy", "verify"):
        if category in by_category:
            waves.append([n["full"] for n in sorted(by_category[category], key=lambda n: n["full"])])

    done = []
    for category in ("prepare", "copy", "verify"):
        category_nodes = sorted(by_category.get(category, []), key=lambda n: n["full"])
        for node in category_nodes:
            if not done:
                node["finish"] = node["duration"]
                node["path"] = [node["full"]]
            else:
                max_finish = max(p["finish"] for p in done)
                candidates = [p for p in done if p["finish"] == max_finish]
                candidates.sort(key=lambda p: p["path"])
                chosen = candidates[0]
                node["finish"] = node["duration"] + chosen["finish"]
                node["path"] = chosen["path"] + [node["full"]]
        done.extend(category_nodes)

    last_category = None
    for category in ("prepare", "copy", "verify"):
        if category in by_category:
            last_category = category

    terminals = sorted(by_category[last_category], key=lambda n: (-n["finish"], n["path"]))
    endpoint = terminals[0]

    return {
        "name": contract["name"],
        "result": {
            "records": records,
            "blocked": False,
            "waves": waves,
            "critical_path": endpoint["path"],
            "makespan": max(n["finish"] for n in nodes),
            "earliest_finish": {n["full"]: n["finish"] for n in nodes},
        },
    }

import math


def _is_int(v):
    return isinstance(v, int) and not isinstance(v, bool)


def _require_int(v, name):
    if not _is_int(v):
        raise ValueError(f"{name} must be an integer")
    return v


def _number(v):
    if isinstance(v, bool):
        raise ValueError("score must be a finite number")
    if isinstance(v, int):
        return v
    if isinstance(v, float):
        if math.isnan(v) or math.isinf(v):
            raise ValueError("score must be a finite number")
        return v
    raise ValueError("score must be a finite number")


def _wrapper_records(payload):
    if not isinstance(payload, dict) or set(payload) != {"name", "result"}:
        raise ValueError("input must be a component wrapper")
    result = payload["result"]
    if not isinstance(result, dict) or "records" not in result:
        raise ValueError("component result must contain records")
    records = result["records"]
    if not isinstance(records, list):
        raise ValueError("component records must be a list")
    return records


def _record(record):
    if not isinstance(record, dict):
        raise ValueError("record must be an object")
    source = record.get("source")
    ident = record.get("id")
    if not isinstance(source, str) or not source.strip():
        raise ValueError("record source must be a non-empty string")
    if not isinstance(ident, str) or not ident.strip():
        raise ValueError("record id must be a non-empty string")
    if record.get("score") is None:
        raise ValueError("record must contain score")
    _number(record["score"])

    tags = record.get("tags")
    if not isinstance(tags, list):
        raise ValueError("record tags must be a list")
    for tag in tags:
        if not isinstance(tag, str):
            raise ValueError("each tag must be a string")

    category = record.get("category")
    if not isinstance(category, str) or category not in ("prepare", "copy", "verify"):
        raise ValueError("category must be prepare/copy/verify")

    return record


