import json
import subprocess
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parent


def contracts():
    return sorted(
        p for p in ROOT.rglob("contract.json")
        if "outputs" not in p.relative_to(ROOT).parts
    )


def main():
    cs = contracts()
    if not cs:
        raise ValueError("no component contracts found")

    output_to_contract = {}
    for path in cs:
        contract = json.loads(path.read_text(encoding="utf-8"))
        output_to_contract[(ROOT / contract["output"]).resolve()] = path

    order = []
    visited = set()
    visiting = set()

    def visit(path):
        key = path.resolve()
        if key in visited:
            return
        if key in visiting:
            raise ValueError("contract dependency cycle")
        visiting.add(key)

        contract = json.loads(path.read_text(encoding="utf-8"))
        for input_path in contract["inputs"]:
            dependency = output_to_contract.get((ROOT / input_path).resolve())
            if dependency is not None and dependency.resolve() != key:
                visit(dependency)

        visiting.remove(key)
        visited.add(key)
        order.append(path)

    for path in cs:
        visit(path)

    for path in order:
        subprocess.run(
            [sys.executable, str(path.with_name("render.py"))],
            cwd=ROOT,
            check=True,
        )

    subprocess.run([sys.executable, str(ROOT / "integrate.py")], cwd=ROOT, check=True)
    subprocess.run([sys.executable, str(ROOT / "final_report.py")], cwd=ROOT, check=True)


if __name__ == "__main__":
    main()

import hashlib
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parent


def _is_number(v):
    return isinstance(v, (int, float)) and not isinstance(v, bool)


def main():
    core_path = ROOT / "outputs" / "core_manifest.json"
    core_object = json.loads(core_path.read_text(encoding="utf-8"))
    if not isinstance(core_object, dict) or not isinstance(core_object.get("components"), dict):
        raise ValueError("core_manifest must be an object with components")

    components = core_object["components"]
    attention = []
    for name, result in components.items():
        if not isinstance(result, dict):
            raise ValueError("component result must be an object")
        flagged = False
        if result.get("blocked") is True:
            flagged = True
        if "feasible" in result and result["feasible"] is False:
            flagged = True
        if "compatible" in result and result["compatible"] is False:
            flagged = True
        deny = result.get("deny")
        if _is_number(deny) and deny > 0:
            flagged = True
        score_total = result.get("score_total")
        if _is_number(score_total) and score_total >= 20:
            flagged = True
        if flagged:
            attention.append(name)

    sha_input = json.dumps(
        core_object,
        ensure_ascii=False,
        sort_keys=True,
        separators=(",", ":"),
        allow_nan=False,
    ).encode("utf-8")

    report = {
        "title": "数仓切换保障",
        "component_count": len(components),
        "sha256": hashlib.sha256(sha_input).hexdigest(),
        "attention": sorted(set(attention)),
    }

    out = ROOT / "outputs" / "final_report.json"
    out.parent.mkdir(parents=True, exist_ok=True)
    out.write_text(
        json.dumps(report, ensure_ascii=False, sort_keys=True, indent=2, allow_nan=False) + "\n",
        encoding="utf-8",
    )


